#pragma once

#include "aegisproxy/http/http_request.hpp"

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace aegis::http {

/// HTTP/1.x response. Either relayed from a backend (TODO: HttpParser response mode)
/// or generated by the proxy itself (502/503/504/501 error pages).
struct HttpResponse {
  HttpVersion version{HttpVersion::Http11};
  int status_code{200};
  std::string reason;
  std::vector<HttpHeader> headers;
  std::string body;

  [[nodiscard]] std::optional<std::string_view> header(std::string_view name) const noexcept;

  /// Serialises status line + headers + CRLF + body. Adds Content-Length if absent.
  [[nodiscard]] std::string serialize() const;
};

/// Standard reason phrase for common status codes ("Bad Gateway" for 502, ...).
[[nodiscard]] std::string_view reason_phrase(int status_code) noexcept;

/// Builds a proxy-generated plain-text error response (Connection: close).
[[nodiscard]] HttpResponse make_error_response(int status_code, std::string_view detail);

}  // namespace aegis::http
